      references: ["鹿群聊天导出中的“何意味”及其变体。", "鹿群人物语言与经典语句分析材料。"],
      categories: ["群聊语言", "语义学", "内部玩笑"],
      related: ["question-rain", "short-messages", "tang-yinxin", "high-cognition", "chat-cycle"]
